  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // DEV-HOUR: 9500 * 5 = 47500, discount 5% (gold tier) = 2375
