  // vat = 10000 * 9 / 100 = 900
  assert.equal(lineVat(line), 900);
});

test('lineVat handles 0% VAT rate', () => {
  const line = { qty: 1, unitPrice: 10000, vatRate: 0, discountPercent: 0 };
  // vat = 10000 * 0 / 100 = 0
  assert.equal(lineVat(line), 0);
});

test('lineVat rounds fractional cents correctly', () => {
  const line = { qty: 3, unitPrice: 333, vatRate: 21, discountPercent: 0 };
  // lineTotal = 999
  // vat = 999 * 21 / 100 = 209.79, rounded to 210
  assert.equal(lineVat(line), 210);
});

test('lineVat clamps to 0 if somehow negative', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: -10 };
  // Even with negative discount, vat should clamp to 0
  assert.equal(lineVat(line), 0);
});

test('invoiceTotals includes vat in return object', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // Should have vat field
  assert(totals.hasOwnProperty('vat'));
});

test('invoiceTotals calculates total with VAT', () => {
  // Create invoice with no discount (standard tier)
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 cents, qty 10 = 95000
  // Discount: 0 (standard tier)
  // VAT: 95000 * 21 / 100 = 19950
  // Total: 95000 - 0 + 19950 = 114950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950);
});

test('invoiceTotals with discount and VAT', () => {
  // Create invoice with gold tier discount (5%)
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 cents, qty 10 = 95000
  // Discount: 95000 * 5 / 100 = 4750
  // Discounted amount: 95000 - 4750 = 90250
  // VAT: 90250 * 21 / 100 = 18952.50, rounded to 18953
  // Total: 95000 - 4750 + 18953 = 109203
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 109203);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 9500 cents, VAT 21%
      { sku: 'COPY-HOUR', qty: 1 }, // 6000 cents, VAT 0%
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500, VAT 21% = 1995
  // COPY-HOUR: 6000, VAT 0% = 0
  // Subtotal: 15500
  // Discount: 0
  // VAT: 1995
  // Total: 17495
  assert.equal(totals.subtotal, 15500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1995);
  assert.equal(totals.total, 17495);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-03-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 1000,
        vatRate: 21,
        discountPercent: 150, // Invalid but for testing clamping
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // subtotal = 1000
  // discount = 1000 * 150 / 100 = 1500
  // discountedAmount = 1000 - 1500 = -500, clamped to 0
  // vat = 0 * 21 / 100 = 0
  // total = max(0, 1000 - 1500 + 0) = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with 9% VAT rate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'COPY-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // COPY-HOUR: 6000 cents, qty 10 = 60000
  // VAT: 60000 * 0 / 100 = 0 (COPY-HOUR has 0% VAT)
  assert.equal(totals.vat, 0);
});

test('invoiceTotals with 21% VAT and discount produces correct total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 * 5 = 47500
  // Discount: 47500 * 5 / 100 = 2375
  // Discounted: 47500 - 2375 = 45125
  // VAT: 45125 * 21 / 100 = 9476.25, rounded to 9476
  // Total: 47500 - 2375 + 9476 = 54601
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

