    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // DEV-HOUR: 9500 * 5 = 47500, discount 5% (gold tier) = 2375
  // DES-HOUR: 8500 * 2 = 17000, discount 5% (gold tier) = 850
  // Subtotal: 64500, Discount: 3225, Total: 61275
  assert.equal(totals.subtotal, 64500);
  assert.equal(totals.discount, 3225);
