test('issueInvoice uses existing numbers to assign next number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-05-20',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

  assert.equal(invoiceResult.ok, true);
  const existing = ['INV-2024-0001', 'INV-2024-0002'];
