  // DEV-HOUR is 9500 cents, qty 10 = 95000
  // Discount 5% = 4750
  // Discounted = 90250
  // VAT 21% = 18952.5 → 18953
  // Total = 109203
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 109203);
});

test('addLine applies tier discount when no discountPercent provided', () => {
