  // lineTotal = 10000
  // discountedAmount = 10000 - 0 = 10000
  // vat = 10000 * 21 / 100 = 2100
  assert.equal(lineVat(line), 2100);
});

test('lineVat calculates VAT on discounted amount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  // lineTotal = 10000
  // discount = 10000 * 10 / 100 = 1000
  // discountedAmount = 10000 - 1000 = 9000
  // vat = 9000 * 21 / 100 = 1890
  assert.equal(lineVat(line), 1890);
});

test('lineVat handles 9% VAT rate', () => {
