    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 9500 cents, VAT 21%
      { sku: 'COPY-HOUR', qty: 1 }, // 6000 cents, VAT 0%
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500, VAT 21% = 1995
  // COPY-HOUR: 6000, VAT 0% = 0
  // Subtotal: 15500
  // Discount: 0
  // VAT: 1995
  // Total: 17495
  assert.equal(totals.subtotal, 15500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1995);
  assert.equal(totals.total, 17495);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-03-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 1000,
        vatRate: 21,
        discountPercent: 150, // Invalid but for testing clamping
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // subtotal = 1000
  // discount = 1000 * 150 / 100 = 1500
  // discountedAmount = 1000 - 1500 = -500, clamped to 0
  // vat = 0 * 21 / 100 = 0
  // total = max(0, 1000 - 1500 + 0) = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with 9% VAT rate', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'COPY-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // COPY-HOUR: 6000 cents, qty 10 = 60000
  // VAT: 60000 * 0 / 100 = 0 (COPY-HOUR has 0% VAT)
  assert.equal(totals.vat, 0);
});

test('invoiceTotals with 21% VAT and discount produces correct total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);

  // DEV-HOUR: 9500 * 5 = 47500
  // Discount: 47500 * 5 / 100 = 2375
  // Discounted: 47500 - 2375 = 45125
  // VAT: 45125 * 21 / 100 = 9476.25, rounded to 9476
  // Total: 47500 - 2375 + 9476 = 54601
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

